def solve(g):
    h=len(g); w=len(g[0])
    # pass 1: sep cols = constant over all rows
    sep=set()
    for c in range(w):
        vals=[g[i][c] for i in range(h)]
        if len(set(vals))==1: sep.add(c)
    # pass 2: line rows = rows uniform over non-sep cols
    lin=[]
    for r in range(h):
        nz=[g[r][c] for c in range(w) if c not in sep]
        if len(set(nz))==1: lin.append(r)
    # passes may cascade; iterate
    changed=True
    while changed:
        changed=False
        newsep=set(); newlin=[]
        for c in range(w):
            vals=[g[i][c] for i in range(h) if i not in lin]
            if len(set(vals))==1: newsep.add(c)
        for r in range(h):
            nz=[g[r][c] for c in range(w) if c not in newsep]
            if len(set(nz))==1: newlin.append(r)
        if newsep!=sep or set(newlin)!=set(lin):
            sep=newsep; lin=newlin; changed=True
    # row groups: consecutive equal rows (original)
    R=[list(g)[0] for _,g in groupby(g)]
    # col groups: consecutive equal col vectors (original)
    Vs=[tuple(g[i][c] for i in range(h)) for c in range(w)]
    Gc=[list(g)[0] for _,g in groupby(Vs)]
    def issep(v): return v in sep
    out=[]
    for r in R:
        row=[]
        for cvec in Gc:
            idx=list(Vs).index(cvec)
            if issep(idx): row.append(g[r][idx])
            else: row.append(r[idx])
        out.append(row)
    return out

